// Parse the Set-Cookie array from AutoCRM's login response into the two
// values every later request needs: the access_token cookie and the
// csrf_token, which must ALSO be echoed as an X-CSRF-Token header on
// POST/PATCH/DELETE (API.md s3, "double-submit CSRF").
const res = $input.first().json;
const raw = res.headers?.['set-cookie'] ?? [];
const list = Array.isArray(raw) ? raw : [raw];

const jar = {};
for (const entry of list) {
  const [pair] = String(entry).split(';');
  const eq = pair.indexOf('=');
  if (eq === -1) continue;
  jar[pair.slice(0, eq).trim()] = pair.slice(eq + 1).trim();
}

if (!jar.access_token) {
  throw new Error('AutoCRM login returned no access_token cookie. Check AUTOCRM_SERVICE_EMAIL / AUTOCRM_SERVICE_PASSWORD and that the user is_active.');
}

return [{
  json: {
    cookieHeader: `access_token=${jar.access_token}; csrf_token=${jar.csrf_token ?? ''}`,
    csrfToken: jar.csrf_token ?? '',
  },
}];

