// One place to derive every meeting value the nodes below need, so the Luxon
// formatting and URL fallbacks are not copy-pasted (and drifting) across a task
// body and two emails.
const b   = $('Webhook').item.json.body;
const run = $input.first().json;
const m   = b.meeting ?? {};

if (!run.crm_lead_id) {
  // meeting_booked is contracted to arrive after lead_created for the same
  // session, so a missing CRM id is a real upstream bug, not a normal state.
  // Fail loudly into Record Failure rather than POST a task with a null entity.
  throw new Error('No crm_lead_id in agent_runs for session ' + b.session_id +
                  '. Did lead_created run first?');
}
if (!m.start_time) throw new Error('meeting.start_time missing from webhook payload');

const zone  = $env.MEETING_TIMEZONE || 'Asia/Karachi';
const start = DateTime.fromISO(m.start_time, { zone: 'utc' });
if (!start.isValid) throw new Error('Unparseable meeting.start_time: ' + m.start_time);

const local = start.setZone(zone);

return [{
  json: {
    crm_lead_id:   run.crm_lead_id,
    visitorName:   b.fields?.visitor_name  ?? run.visitor_name  ?? 'there',
    visitorEmail:  b.fields?.visitor_email ?? run.visitor_email ?? '',
    companyName:   b.fields?.company_name  ?? '',
    // Surfaced for the prep task: a rep who cannot phone the visitor
    // cannot rescue a no-show.
    visitorPhone:  b.fields?.visitor_phone ?? '',
    // due_at is TIMESTAMPTZ: send UTC ISO and let AutoCRM render per-user.
    dueAt:         start.toISO(),
    whenLocal:     local.toFormat("cccc d LLLL yyyy 'at' h:mm a") + ' (' + local.offsetNameShort + ')',
    // Cal.com only guarantees reschedule/cancel links; a video location is
    // optional, so fall back rather than emailing the word "undefined".
    joinUrl:       m.meeting_url ?? m.location ?? m.reschedule_url ?? '',
    rescheduleUrl: m.reschedule_url ?? '',
    cancelUrl:     m.cancel_url ?? '',
    // Cal.com booking identity. cal_booking_uid is the ONLY join key inbound
    // Cal webhooks can use -- BOOKING_CANCELLED omits booking metadata
    // (calcom/cal.com#27783), so it never carries our session_id.
    calBookingUid: m.uid ?? m.booking_uid ?? null,
    calStatus:     m.status ?? 'accepted',
  },
}];

